340	func convertInstanceSettingFromRaw(instanceSettingRaw *InstanceSetting) (*storepb.InstanceSetting, error) {
341		instanceSetting := &storepb.InstanceSetting{
342			Key: storepb.InstanceSettingKey(storepb.InstanceSettingKey_value[instanceSettingRaw.Name]),
343		}
344		switch instanceSettingRaw.Name {
345		case storepb.InstanceSettingKey_BASIC.String():
346			basicSetting := &storepb.InstanceBasicSetting{}
347			if err := protojsonUnmarshaler.Unmarshal([]byte(instanceSettingRaw.Value), basicSetting); err != nil {
348				return nil, err
349			}
350			instanceSetting.Value = &storepb.InstanceSetting_BasicSetting{BasicSetting: basicSetting}
351		case storepb.InstanceSettingKey_GENERAL.String():
352			generalSetting := &storepb.InstanceGeneralSetting{}
353			if err := protojsonUnmarshaler.Unmarshal([]byte(instanceSettingRaw.Value), generalSetting); err != nil {
354				return nil, err
355			}
356			instanceSetting.Value = &storepb.InstanceSetting_GeneralSetting{GeneralSetting: generalSetting}
357		case storepb.InstanceSettingKey_STORAGE.String():
358			storageSetting := &storepb.InstanceStorageSetting{}
359			if err := protojsonUnmarshaler.Unmarshal([]byte(instanceSettingRaw.Value), storageSetting); err != nil {
360				return nil, err
361			}
362			instanceSetting.Value = &storepb.InstanceSetting_StorageSetting{StorageSetting: storageSetting}
363		case storepb.InstanceSettingKey_MEMO_RELATED.String():
364			memoRelatedSetting := &storepb.InstanceMemoRelatedSetting{}
365			if err := protojsonUnmarshaler.Unmarshal([]byte(instanceSettingRaw.Value), memoRelatedSetting); err != nil {
366				return nil, err
367			}
368			instanceSetting.Value = &storepb.InstanceSetting_MemoRelatedSetting{MemoRelatedSetting: memoRelatedSetting}
369		case storepb.InstanceSettingKey_TAGS.String():
370			tagsSetting := &storepb.InstanceTagsSetting{}
371			if err := protojsonUnmarshaler.Unmarshal([]byte(instanceSettingRaw.Value), tagsSetting); err != nil {
372				return nil, err
373			}
374			instanceSetting.Value = &storepb.InstanceSetting_TagsSetting{TagsSetting: tagsSetting}
375		case storepb.InstanceSettingKey_NOTIFICATION.String():
376			notificationSetting := &storepb.InstanceNotificationSetting{}
377			if err := protojsonUnmarshaler.Unmarshal([]byte(instanceSettingRaw.Value), notificationSetting); err != nil {
378				return nil, err
379			}
380			instanceSetting.Value = &storepb.InstanceSetting_NotificationSetting{NotificationSetting: notificationSetting}
381		case storepb.InstanceSettingKey_AI.String():
382			aiSetting := &storepb.InstanceAISetting{}
383			if err := protojsonUnmarshaler.Unmarshal([]byte(instanceSettingRaw.Value), aiSetting); err != nil {
384				return nil, err
385			}
386			instanceSetting.Value = &storepb.InstanceSetting_AiSetting{AiSetting: aiSetting}
387		default:
388			// Skip unsupported instance setting key.
389			return nil, nil
390		}
391		return instanceSetting, nil
392	}
